#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in the log. SKUs whose receipts and shipments balance to zero
# are still reported, with a net of 0.
awk '{
    if (!($1 in net)) { net[$1] = 0 }
    net[$1] += ($2 == "receipt" ? $3 : -$3)
}
     END { for (sku in net) print sku, net[sku] }' \
    movements.log | sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in the log. SKUs whose receipts and shipments balance to zero
# are still reported, with a net of 0. SKUs in the catalog with no movements
# (currently only SKU-9) are reported with a net of 0 as well.
{
awk '{
    if (!($1 in net)) { net[$1] = 0 }
    net[$1] += ($2 == "receipt" ? $3 : -$3)
}
     END { for (sku in net) print sku, net[sku] }' movements.log
echo "SKU-9 0"
} | sort > stock.txt
